from __future__ import annotations

import hashlib

MASK_FILL = "********"


def value(raw: str) -> str:
    visible = 4
    if len(raw) <= visible * 2:
        return MASK_FILL
    return raw[:visible] + MASK_FILL + raw[len(raw) - visible :]


def value_with_length_hint(raw: str, reveal_length: bool) -> str:
    v = value(raw)
    if not reveal_length:
        return v
    if len(raw) <= 16:
        bucket = "short"
    elif len(raw) <= 40:
        bucket = "medium"
    else:
        bucket = "long"
    return f"{v} ({bucket})"


def context(line: str, raw_secret: str) -> str:
    if not raw_secret:
        return line
    return line.replace(raw_secret, value(raw_secret))


def hash_value(raw: str) -> str:
    return hashlib.sha256(raw.encode()).hexdigest()


def hash_file(path: str) -> str:
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()
